<?php require 'config.php';if(empty($_SESSION['user_id']))go('login.php');$s=$pdo->prepare('SELECT * FROM complaints WHERE user_id=? ORDER BY id DESC');$s->execute([$_SESSION['user_id']]);$rows=$s->fetchAll();$title='My Complaints';require 'partials/top.php';?><section class="glass panel"><h3>My Complaints</h3><p>Your complaint history and current status.</p><a class="button" href="new_complaint.php">＋ New Complaint</a><div class="tablewrap"><table><tr><th>ID</th><th>Title</th><th>Department</th><th>Status</th><th>Admin Remarks</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['complaint_code'])?></td><td><?=e($r['title'])?></td><td><?=e($r['department'])?></td><td><span class="status"><?=e($r['status'])?></span></td><td><?=e($r['admin_remarks']??'—')?></td></tr><?php endforeach;?></table></div></section><?php require 'partials/bottom.php';?>